// Characterisation tests: record what the current AckerDiffController computes,
// so that refactoring (extracting a ROS-free core) and the Humble port can be
// checked against today's behaviour. These values are NOT a specification;
// a deliberate behaviour change must update them in its own commit.
//
// Golden values were generated by running the original controller code
// (before the core was extracted, commit 96a0497) on ROS 2 Foxy. They must
// keep passing unchanged against the extracted core.

#include <gtest/gtest.h>

#include <chrono>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <vector>

#include "acker_diff_controller/acker_diff_core.hpp"
#include "acker_diff_controller/odometry.hpp"

namespace
{
// Geometry from pilsbot_hw_ros/pilsbot_control/config/acker_diff_controller.yaml
constexpr double kSeparation = 0.62;
constexpr double kRadius = 0.125;
constexpr double kWheelbase = 0.67;

using acker_diff_controller::WheelGeometry;
using acker_diff_controller::WheelPair;

WheelGeometry pilsbot_geometry()
{
  WheelGeometry g;
  g.separation = kSeparation;
  g.radius = kRadius;
  g.wheelbase = kWheelbase;
  return g;
}

// Seconds exactly as rclcpp::Time::seconds() computes them from nanoseconds.
double seconds(double t)
{
  return std::chrono::duration<double>(
    std::chrono::nanoseconds(static_cast<int64_t>(t * 1e9))).count();
}

struct TurningCase { double speed; double angle; double left; double right; };
struct MixCase { double lin_left; double lin_right; double angular; double left; double right; };
struct OdomSample { double x; double y; double heading; double linear; double angular; };

bool generate() { return std::getenv("GENERATE_GOLDEN") != nullptr; }

}  // namespace

TEST(Characterisation, turning_speeds)
{
  const std::vector<TurningCase> cases = {
    {0.5, 0.29999999999999999, 0.55941200517142997, 0.42483300576596755},
    {0.5, -0.29999999999999999, 0.42483300576596755, 0.55941200517142997},
    {-0.5, 0.29999999999999999, -0.55941200517142997, -0.42483300576596755},
    {1.2, 1, 1.0896036199102783, 0.47891916168170251},
    {1.2, -1.2, 0.42156088666308517, 1.0608300804325606},
    {0.5, 0.059999999999999998, 0.51352967261220384, 0.48580362952650696},
    {0, 0.5, 0, 0},
    {0.80000000000000004, 1.45, 0.8568804496194421, 0.31747939672231595},
  };
  for (const auto & c : cases) {
    const auto r = acker_diff_controller::calc_turning_speeds(pilsbot_geometry(), c.speed, c.angle);
    if (generate()) {
      std::printf("    {%.17g, %.17g, %.17g, %.17g},\n", c.speed, c.angle, r.left, r.right);
      continue;
    }
    EXPECT_DOUBLE_EQ(r.left, c.left) << "speed " << c.speed << " angle " << c.angle;
    EXPECT_DOUBLE_EQ(r.right, c.right) << "speed " << c.speed << " angle " << c.angle;
  }
}

TEST(Characterisation, mix_linear_and_angular)
{
  const std::vector<MixCase> cases = {
    {0.5, 0.5, 0, 4, 4},
    {0.5, 0.5, 0.40000000000000002, 3.008, 4.992},
    {0.5, 0.5, -0.40000000000000002, 4.992, 3.008},
    {0.59999999999999998, 0.40000000000000002, 0.25, 4.1799999999999997, 3.8200000000000003},
    {-0.29999999999999999, -0.29999999999999999, 1, -4.8799999999999999, 0.080000000000000071},
    {0, 0, 1, -2.48, 2.48},
  };
  for (const auto & c : cases) {
    const auto r = acker_diff_controller::mix_linear_and_angular(
      pilsbot_geometry(), WheelPair{c.lin_left, c.lin_right}, c.angular);
    if (generate()) {
      std::printf("    {%.17g, %.17g, %.17g, %.17g, %.17g},\n",
        c.lin_left, c.lin_right, c.angular, r.left, r.right);
      continue;
    }
    EXPECT_DOUBLE_EQ(r.left, c.left);
    EXPECT_DOUBLE_EQ(r.right, c.right);
  }
}

// Wheel-position odometry exactly as the controller drives it: odometry.init()
// is never called by the controller, so the first update integrates against t=0.
TEST(CharacterisationOdometry, closed_loop_sequence)
{
  acker_diff_controller::Odometry odom(10);
  odom.setWheelParams(kSeparation, kRadius, kRadius);

  struct Step { double t; double left_pos; double right_pos; };
  const std::vector<Step> steps = {
    {100.00, 0.0, 0.0},
    {100.02, 0.08, 0.08},
    {100.04, 0.16, 0.17},
    {100.06, 0.23, 0.27},
    {100.08, 0.29, 0.38},
    {100.10, 0.34, 0.50},
    {100.12, 0.38, 0.62},
    {100.14, 0.41, 0.73},
    {100.16, 0.43, 0.83},
    {100.18, 0.44, 0.92},
    {100.20, 0.44, 1.00},
    {100.22, 0.44, 1.00},
  };
  const std::vector<OdomSample> golden = {
    {0, 0, 0, 0, 0},
    {0.01, 0, 0, 0.25000000000004974, 0},
    {0.020624992801960146, 1.0710681855657925e-05, 0.0020161290322580662, 0.34374999999994255, 0.033602150537617247},
    {0.031249841643591285, 6.4263800891914966e-05, 0.0080645161290322596, 0.39062499999998335, 0.1008064516129054},
    {0.041873884321072814, 0.00020349813726936442, 0.018145161290322585, 0.41875000000000784, 0.18145161290324766},
    {0.052495422269992688, 0.00047123470922765919, 0.032258064516129031, 0.43750000000002415, 0.26881720430111677},
    {0.06248718551330306, 0.00087434688685384711, 0.048387096774193547, 0.44642857142855558, 0.34562211981564489},
    {0.071223152339461568, 0.0013680308373780798, 0.064516129032258063, 0.445312499999997, 0.40322580645161255},
    {0.078703325116298864, 0.0019119019676598183, 0.080645161290322565, 0.43750000000000561, 0.44802867383514289},
    {0.084928681862911942, 0.0024656045560154868, 0.096774193548387094, 0.42499999999998905, 0.48387096774191002},
    {0.089901175234615646, 0.0029888327116917397, 0.1129032258064516, 0.44999999999999407, 0.56451612903224857},
    {0.089901175234615646, 0.0029888327116917397, 0.1129032258064516, 0.39999999999998409, 0.56451612903224857},
  };

  for (size_t i = 0; i < steps.size(); ++i) {
    const auto & s = steps[i];
    odom.update(s.left_pos, s.right_pos, seconds(s.t));
    if (generate() || golden.empty()) {
      std::printf("    {%.17g, %.17g, %.17g, %.17g, %.17g},\n",
        odom.getX(), odom.getY(), odom.getHeading(), odom.getLinear(), odom.getAngular());
      continue;
    }
    EXPECT_DOUBLE_EQ(odom.getX(), golden[i].x) << "step " << i;
    EXPECT_DOUBLE_EQ(odom.getY(), golden[i].y) << "step " << i;
    EXPECT_DOUBLE_EQ(odom.getHeading(), golden[i].heading) << "step " << i;
    EXPECT_DOUBLE_EQ(odom.getLinear(), golden[i].linear) << "step " << i;
    EXPECT_DOUBLE_EQ(odom.getAngular(), golden[i].angular) << "step " << i;
  }
  if (!generate()) {
    ASSERT_FALSE(golden.empty()) << "golden values missing; run with GENERATE_GOLDEN=1";
  }
}

TEST(CharacterisationOdometry, open_loop_sequence)
{
  acker_diff_controller::Odometry odom(10);
  odom.setWheelParams(kSeparation, kRadius, kRadius);

  struct Step { double t; double linear; double angular; };
  const std::vector<Step> steps = {
    {100.00, 0.0, 0.0},
    {100.02, 0.5, 0.0},
    {100.04, 0.5, 0.3},
    {100.06, 0.5, 0.6},
    {100.08, 0.4, -0.2},
    {100.10, -0.2, 0.0},
  };
  const std::vector<OdomSample> golden = {
    {0, 0, 0, 0, 0},
    {0.0099999999999980105, 0, 0, 0.5, 0},
    {0.019999940000111127, 2.9999910000078064e-05, 0.0060000000000030697, 0.5, 0.29999999999999999},
    {0.029999160013177036, 0.00014999631003940564, 0.018000000000000682, 0.5, 0.59999999999999998},
    {0.037998130702370979, 0.00027799076344634888, 0.014000000000001477, 0.40000000000000002, -0.20000000000000001},
    {0.033998522695969147, 0.00022199259276176004, 0.014000000000001477, -0.20000000000000001, 0},
  };

  for (size_t i = 0; i < steps.size(); ++i) {
    const auto & s = steps[i];
    odom.updateOpenLoop(s.linear, s.angular, seconds(s.t));
    if (generate() || golden.empty()) {
      std::printf("    {%.17g, %.17g, %.17g, %.17g, %.17g},\n",
        odom.getX(), odom.getY(), odom.getHeading(), odom.getLinear(), odom.getAngular());
      continue;
    }
    EXPECT_DOUBLE_EQ(odom.getX(), golden[i].x) << "step " << i;
    EXPECT_DOUBLE_EQ(odom.getY(), golden[i].y) << "step " << i;
    EXPECT_DOUBLE_EQ(odom.getHeading(), golden[i].heading) << "step " << i;
  }
  if (!generate()) {
    ASSERT_FALSE(golden.empty()) << "golden values missing; run with GENERATE_GOLDEN=1";
  }
}
